import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the deciding parameter _baseToken which must be an address; the property:
    // After initialize(...), c.baseToken() == _baseToken for the correct contract.
    // The mutant sets baseToken = address(0) and thus will violate this for many inputs.
