            // if initialize reverts (e.g., AlreadyInitialized / FeeRateTooHigh), record as not ok
            ok = false;
        }

        // Only assert when initialize succeeded; when it succeeds, correct contract guarantees baseToken == argument
        if (ok) {
            assertTrue(c.baseToken() == baseToken_);
        } else {
            // If initialization reverted, we cannot inspect baseToken reliably; assert nothing (test still valid)
            // But must have only one assertTrue in function per task instructions; so we avoid asserting here.
            // To satisfy the requirement of having exactly one assertion that distinguishes mutant, we ensure it's inside the ok branch above.
        }
    }
