pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    event Initialize(address indexed baseToken, address indexed nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties);

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed deciding parameters: _feeRate and _changeFee plus two boolean flags and two small reserves
    function testFuzz_property(uint16 _feeRate, uint56 _changeFee, uint128 _vBase, uint128 _vNft, bool _useOracle, bool _payRoyalties) public {
        // keep inputs in wide admissible ranges but respect feeRate limit check in initialize
        _feeRate = uint16(bound(_feeRate, 0, 5000)); // initialize reverts if >5000

        // prepare calldata for initialize and capture the emitted event by using address(this) as factory/royalty/stolen oracle
        // We will call initialize via this contract as an external actor to capture logs

        // Make the call as a fresh address to emulate arbitrary caller
        address caller = address(0xABCD);
        vm.prank(caller);

        // Call initialize and capture if it reverted
        bool ok;
        try c.initialize(address(0), address(1), _vBase, _vNft, _changeFee, _feeRate, bytes32(0), _useOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize reverted, then the invariant (about stored feeRate vs emitted event) is vacuously about successful initialize only.
        // We assert only when initialize succeeded.
        if (!ok) return;

        // read stored feeRate
        uint16 stored = c.feeRate();

        // Now parse the logs to recover the emitted Initialize event's feeRate argument.
        // forge-std Test exposes getRecordedLogs via vm, but we cannot use vm.load etc.; instead we rely on the fact that the Initialize event signature and parameters are known
        // We will reconstruct the expected emitted feeRate value: it must equal the argument we passed in (_feeRate).
        // The distinguishing property (different from previously tried direct equality) is to require equality between the stored getter and the value that the contract emitted — we can recover emitted value by scanning logs recorded by the EVM via a low-level approach: using abi.decode on the last log's data. forge's vm does not provide a direct logs accessor here, but solidity can read events only via indexed topic inspection which is not accessible. However, we can instead re-check the emission indirectly by calling a view that returns the same parameters — the Initialize event encodes the parameters but we cannot read them; instead we rely on a deterministic relation: the contract set initialized=true then emitted Initialize with the original arguments. The mutant can cause stored feeRate to not equal the emitted feeRate argument; since we cannot directly read event payloads here, we use an alternative observable: the contract's public variable changeFee returns the stored changeFee; the Initialize event includes the changeFee positional argument (the 5th parameter). For the reference contract the stored changeFee equals the emitted changeFee argument, and stored feeRate equals emitted feeRate argument; because the only difference between reference and mutant is write ordering between these two assignments, there exist inputs where the emitted tuple will contain differing values vs the stored ones in the mutant. Concretely, if the mutant results in feeRate and changeFee being swapped in storage relative to the arguments and/or emitted values, then comparing stored changeFee to the _changeFee argument and stored feeRate to the _feeRate argument will catch the discrepancy. We therefore assert both stored values equal the passed-in arguments.

        // Single assertion required by harness: check both stored values equal their corresponding initialize arguments
        // This single assertTrue composes the two equalities with logical AND.
        assertTrue(stored == _feeRate && c.changeFee() == _changeFee);
    }
}
